Qty convertQty(Qty _qty, UnitOfMeasureSymbol _fromUnitId, UnitOfMeasureSymbol _toUnitId, ItemId _itemId)
{
    _qty = UnitOfMeasureConverter::convert(_qty,UnitOfMeasure::findBySymbol(_fromUnitId).RecId,UnitOfMeasure::findBySymbol(_toUnitId).RecId,NoYes::Yes);
    return _qty;
}

    Public Qty salesQtyCalc(InventSum _inventSum,FormDataSource _inventDim_ds,Qty _inventQty)
    {
       
        InventItemSalesSetup    inventItemSalesSetup;
        InventTable inventTable;
        UnitOfMeasureConversion  unitOfMeasureConversion;
        InventSum inventSumLoc;
        InventDim   inventDim,currentInventDim;
        Qty salesQty;
        Common inventDimJoined = formJoinedRecord(_inventSum, _inventDim_ds);
        currentInventDim = inventDimJoined;

        select inventSumLoc
            where inventSumLoc.ItemId == _inventSum.ItemId
                 join inventDim where inventDim.inventDimId == inventSumLoc.InventDimId
                      && inventDim.InventSiteId == inventSumLoc.InventSiteId
                      && inventDim.InventSiteId == currentInventDim.InventSiteId;

        inventItemSalesSetup = InventItemSalesSetup::find(_inventSum.ItemId,inventDim.InventDimId);
        inventTable = InventTable::find(_inventSum.ItemId);
        
        select  unitOfMeasureConversion
            where unitOfMeasureConversion.Product == inventTable.Product
            && unitOfMeasureConversion.FromUnitOfMeasure==UnitOfMeasure::unitOfMeasureIdBySymbol(inventItemSalesSetup.METSalesUnit)
            && unitOfMeasureConversion.ToUnitOfMeasure==UnitOfMeasure::unitOfMeasureIdBySymbol(inventTable.inventUnitId())
            && unitOfMeasureConversion.Rounding==UnitOfMeasureConversionRounding::Nearest;

        if(unitOfMeasureConversion.Factor)
        {
            salesQty = _inventQty/unitOfMeasureConversion.Factor;
        }

        return salesQty;
    }

    display public InventQtyAvailPhysical availPhysicalSales(InventSum _inventSum)
    {
        InventQtyAvailPhysical qty,inventQty;
        FormDataSource inventDim_ds = this.formRun().dataSource(FormDataSourceStr(InventOnhandItem,InventDim));

        
        //salesQty = this.convertQty(this.availPhysical(_inventSum),inventItemSalesSetup.METSalesUnit,inventTable.inventUnitId(),inventTable.ItemId);
        inventQty = this.availPhysical(_inventSum);
        qty = this.salesQtyCalc(_inventSum,inventDim_ds,inventQty);

        return  qty;
    }

    display public InventQtyPhysicalOnhand physicalInventSales(InventSum _inventSum)
